package com.hostel.hostelmanagement.filter; import com.hostel.hostelmanagement.repository.UserRepository; import com.hostel.hostelmanagement.security.JwtService; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List; @Component public class JwtAuthenticationFilter extends OncePerRequestFilter { final JwtService jwt; final UserRepository users; public JwtAuthenticationFilter(JwtService j,UserRepository u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain chain)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7);if(jwt.valid(t)){String e=jwt.email(t);users.findByEmail(e).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.getEmail(),null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole().name())))));}}chain.doFilter(r,p);} }